__NUXT_JSONP__("/svet/mesto/patra", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M,N,O,P,Q,R,S){return {data:[{place:[{id:n,id_state:o,name:p,population:214580,area:334.82,altitude:q,slug:k,information_chatgpt:"\u003Cp\u003EPatra je přístavní město nacházející se na západním pobřeží Řecka, ve státě Peloponés. Je to třetí největší město v zemi a důležité kulturní, administrativní a obchodní centrum. Patra má bohatou historii, která sahá až do starověku, a nabízí návštěvníkům mnoho zajímavých památek a aktivit.\u003C\u002Fp\u003E\n\u003Cp\u003EJedním z nejvýznamnějších symbolů města je Patrský amfiteátr, který se nachází na hoře Panachaikon. Tento starobylý amfiteátr byl postaven ve 2. století a nabízí nádherný výhled na město a záliv Korintského moře. Každý rok se zde konají kulturní akce a festivaly, včetně známého Karnevalu Patra, který je největším karnevale v Řecku a jedním z největších na světě.\u003C\u002Fp\u003E\n\u003Cp\u003EMezi další významné památky v Patře patří pevnost Patras, která se tyčí nad městem a nabízí panoramatické výhledy, a starověký římský Odeon, který byl původně divadlem a dnes slouží jako koncertní místo. Navštívit můžete také Archeologické muzeum Patras, které představuje bohatou sbírku archeologických artefaktů z regionu.\u003C\u002Fp\u003E\n\u003Cp\u003EMěsto Patra je také známé svou živou a energickou atmosférou. Najdete zde mnoho tradičních tavern a restaurací, kde si můžete vychutnat řeckou kuchyni a ochutnat místní speciality. Patra je také známá svým nočním životem, kde se večer ožívá mnoho barů a klubů.\u003C\u002Fp\u003E\n\u003Cp\u003EV blízkosti města se nacházejí nádherné pláže, jako například Río, která je jednou z nejpopulárnějších pláží v okolí. Tato pláž nabízí čisté modré moře a písečné pláže, ideální pro relaxaci a slunění.\u003C\u002Fp\u003E",coordinates:[{latitude:38.2466,longitude:21.7346}],biggest:"yes",type_place:a,id_image_cover:i,id_image_hero:i,affiliate:[{name:r,value:s}],alerts:b,zoom:[{google:10,booking:11}],parking:b,information_author:b,importance:e,seo_tags:b,created_at:"2023-12-27T16:36:26.534285+00:00",updated_at:"2023-12-27T17:06:48.496338+00:00",name_original:b}],imagePlace:[{id:i,name:k,source:f,type:a,author:g,created_at:h,updated_at:d}],placeState:[{tld:".gr",name:"Řecko",area:131957,population:10724599,slug:t,id_continent:j,information_chatgpt:"\u003Cp\u003EŘecko je země s bohatou historií a kulturou, která se rozprostírá na jihovýchodním cípu Evropy. Země je známá svými krásnými plážemi, nezapomenutelnými památkami a vynikající kuchyní. Řecko bylo rodištěm mnoha významných osobností, jako jsou Homér, Platón, Aristoteles a Sokrates.\u003C\u002Fp\u003E\n\u003Cp\u003EVe starověkém Řecku se narodily některé z nejvýznamnějších myšlenek a poznatků, které ovlivnily celý svět. Země je domovem mnoha archeologických nalezišť, jako jsou Akropolis v Athénách, chrám bohyně Athény, nebo archeologická lokalita v Delfách, kde se nacházel slavný chrám boha Apollóna.\u003C\u002Fp\u003E\n\u003Cp\u003EV dnešní době je Řecko oblíbeným cestovatelským cílem pro své nádherné pláže a turistická letoviska. Mezi nejpopulárnější turistické oblasti patří ostrovy jako Santorini, Mykonos a Kréta, které nabízejí úchvatné výhledy na modré moře, bílé domy a slunce západu. Kromě pláží můžete v Řecku objevovat také horské vesnice, malebné uličky a tradiční taverenky.\u003C\u002Fp\u003E\n\u003Cp\u003EŘecká kuchyně je plná chutí a vůní. Mezi nejtypičtější jídla patří suflaki, gyros, tzatziki, feta s olivami a zeleninou a moussaka. Země je také známá svými sladkostmi, jako jsou baklava a loukoumades, což jsou fritované kuličky podávané s medem a skořicí.\u003C\u002Fp\u003E\n\u003Cp\u003EŘecko je skvělou volbou pro ty, kteří hledají spojení historie, kultury a přírody. Země nabízí návštěvníkům nekonečné množství aktivit, jako jsou plavby, potápění, turistika a poznávání památek. Ať už cestujete s rodinou, přáteli nebo sami, Řecko vám přinese nezapomenutelné zážitky a krásné vzpomínky.\u003C\u002Fp\u003E",currency_code:"EUR",currency_name:"euro",money_prices:[{name:"Taxi (cena za km)",value:.9,date_update:c},{name:"Hlavní jídlo",value:12,date_update:c},{name:"Chleba",value:.7,date_update:c},{name:"Mléko",value:1.2,date_update:c},{name:"Voda (500ml)",value:.5,date_update:c},{name:"Espresso",value:l,date_update:c},{name:"Zmrzlina (jeden kopeček)",value:l,date_update:c},{name:"Pivo",value:j,date_update:c},{name:"Krabička cigaret",value:b,date_update:c},{name:"Bic Mac",value:3.5,date_update:c},{name:"Coca Cola (500ml)",value:l,date_update:c}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:c},{name:"Policie",value:"100",date_update:c},{name:"Hasiči",value:"199",date_update:c},{name:"Zdravotnická záchranná služba",value:"166",date_update:c},{name:"Turistická policie",value:"171",date_update:c},{name:"Horská záchranná služba",value:"118",date_update:c},{name:"Pobřežní záchranná služba",value:"108",date_update:c}],phone_prefix:"+30",coordinates:[{latitude:"39.0742",longitude:"21.8243"}],people_religion:[{name:"Pravoslavné křesťanství",value:"90 %"},{name:"Muslimové",value:u},{name:"Římští katolíci",value:u},{name:"Judaismus",value:"0,5 %"},{name:"Jiné náboženství nebo bez vyznání",value:"5,5 %"}],people_nationality:[{name:"Řekové",value:"93,0 %"},{name:"Albánci",value:"2,0 %"},{name:"Romové",value:"1,5 %"},{name:"Pákistánci",value:"0,8 %"},{name:"Bulhaři",value:"0,6 %"},{name:"Jiné",value:"2,1 %"}],visitors_entry:[{name:"Občanský průkaz",value:"Pro občany Evropské unie je pro vstup do Řecka postačující občanský průkaz. Není tedy potřeba mít cestovní pas.",date_update:v},{name:"Cestovní pas",value:"Pro vstup do Řecko není pro občany Evropské unie vyžadován cestovní pas.",date_update:v},{name:"Vízum",value:"Pro občany ČR, kteří chtějí pobývat v Řecku do 90 dnů, není potřeba žádné vízum. Pokud by pobyt měl přesáhnout 90 dnů, je nutné si zajistit pobytové oprávnění. Pokud cestujete s jinou státní příslušností, informujte se o konkrétních vízových podmínkách na stránkách řeckého velvyslanectví v dané zemi.",date_update:w},{name:"Očkování",value:"Pro vstup do Řecka není nutné mít žádné speciální očkování. Nicméně vzhledem k pandemii Covid-19 je pro vstup na území Řecka nutné mít potvrzení o negativním testu na Covid-19 ne starší než 72 hodin, nebo potvrzení o plném očkování nebo potvrzení o prodělané nemoci COVID-19. Pokud tuto podmínku nesplníte, může být vstup na území Řecka odepřen.",date_update:w},{name:"Cestovní pojištění",value:"Pro vstup do Řecka není vyžadováno cestovní ani zdravotní pojištění. Nicméně doporučuje se mít cestovní pojištění pokrývající lékařské výlohy a repatriaci v případě potřeby.",date_update:c},{name:"Bezpečnostní situace",value:"Řecko obecně patří mezi bezpečné země a turisté zde běžně cestují bez problémů. Nicméně je třeba dodržovat základní bezpečnostní opatření, zejména v turistických centrech a na plážích, kde se mohou vyskytovat kapsáři a zloději. Také je třeba dbát obezřetnosti v blízkosti protestů a demonstrací, které se občas v Řecku konají.",date_update:c},{name:"Další informace",value:"V Řecku se platí eurem. Je dobré mít s sebou hotovost, protože některé menší obchody a restaurace mohou platbu kartou neakceptovat. V letních měsících může být velmi horko, a proto je vhodné mít s sebou dostatek pitné vody a chránit se před sluncem. Řecko je také známé svou bohatou historií a kulturou, a proto je doporučeno navštívit některé z jeho archeologických nalezišť a muzeí.",date_update:c}],type_place:x,id_image_cover:m,id_image_hero:m,id_city_main:y,affiliate:[{name:r,value:s}],mpz:"GR",alerts:b,zoom:[{google:z,booking:q}],ids_neighboring_countries:[{id:144},{id:z},{id:22},{id:225}],organization:b,apps:b,links:b,information_author:b,seo_tags:b,language_phrases:b,wall_sockets:b,id:o,facts_place:b,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00",name_original:b}],imageState:[{id:m,name:t,source:"\u002Fworld\u002Fstates\u002F",type:x,author:g,created_at:"2023-05-04T07:17:51.463854+00:00",updated_at:d}],placeContinent:[{id:j,slug:"evropa",name:"Evropa",area:10180000,population:746000000,population_density:73.22,number_states:44,information_chatgpt:"\u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E je druhým nejmenším kontinentem na světě, ale zároveň se jedná o jednu z nejvíce rozmanitých oblastí na planetě. Nachází se zde mnoho historických a kulturních památek, překrásných přírodních scenérií a mnoho dalších atrakcí, což z ní dělá jednu z nejnavštěvovanějších turistických destinací na světě.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E má dlouhou a bohatou historii. Na kontinentě se odehrály mnohé důležité události, jako například římská říše, středověké křížové výpravy, renesance, průmyslová revoluce a dvě světové války. Tato historie se odráží v architektuře, muzeích a dalších kulturních památkách, které jsou na kontinentu k vidění.\u003C\u002Fp\u003E\n\u003Cp\u003EV \u003Cb\u003EEvropě\u003C\u002Fb\u003E se nachází mnoho zajímavých měst. Například \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fpariz\"\u003EPaříž\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Flondyn\"\u003ELondýn\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Frim\"\u003EŘím\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fbarcelona\"\u003EBarcelona\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fpraha\"\u003EPraha\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Fberlin\"\u003EBerlín\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fmesto\u002Famsterdam\"\u003EAmsterdam\u003C\u002Fa\u003E\u003C\u002Fb\u003E jsou velmi oblíbenými cíli turistů. Tyto města nabízejí nejen historické památky, ale také vynikající kuchyni, noční život a mnoho možností pro nákupy.\u003C\u002Fp\u003E\n\u003Cp\u003EPřírodní krása \u003Cb\u003EEvropy\u003C\u002Fb\u003E je také úžasná. Nachází se zde krásné pláže, hory, řeky a jezera. \u003Cb\u003EAlpské hory\u003C\u002Fb\u003E nabízejí překrásné scenérie, skvělé podmínky pro lyžování a další outdoorové aktivity. Národní parky, jako třeba \u003Cb\u003EPlitvická jezera\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fchorvatsko\"\u003EChorvatsku\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003EKrkonošský národní park\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fcesko\"\u003EČeské republice\u003C\u002Fa\u003E\u003C\u002Fb\u003E nebo \u003Cb\u003ENárodní park Durmitor\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fcerna-hora\"\u003EČerné Hoře\u003C\u002Fa\u003E\u003C\u002Fb\u003E, jsou dalšími příklady nádherných přírodních scenérií, které stojí za návštěvu.\u003C\u002Fp\u003E\n  \u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E také nabízí širokou škálu kulturních aktivit. Existují zde mnohé umělecké festivaly, výstavy, divadelní představení a koncerty, které jsou pořádány po celém kontinentu. Mnoho měst také pořádá tradiční slavnosti a jarmarky, kde se můžete seznámit s místními tradicemi a kulturou.\u003C\u002Fp\u003E\n  \u003Cp\u003EPři návštěvě \u003Cb\u003EEvropy\u003C\u002Fb\u003E si určitě nenechte ujít místní kuchyni. Každá země má své vlastní speciality a chuťě\u003C\u002Fp\u003E\u003Cp\u003EMezi nejznámější evropské kuchyně patří \u003Cb\u003Eitalská\u003C\u002Fb\u003E, \u003Cb\u003Efrancouzská\u003C\u002Fb\u003E a \u003Cb\u003Ešpanělská\u003C\u002Fb\u003E. \u003Cb\u003EItalská kuchyně\u003C\u002Fb\u003E je známá svými \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fpasta\"\u003Etěstovinami\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fpizza\"\u003Epizzou\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003Ezmrzlinou\u003C\u002Fb\u003E. \u003Cb\u003EFrancouzská kuchyně\u003C\u002Fb\u003E nabízí širokou škálu různých pokrmů, jako například sýry, pečivo, maso a víno. \u003Cb\u003EŠpanělská kuchyně\u003C\u002Fb\u003E je známá svými \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Ftapas\"\u003Etapas\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fpaella\"\u003Epaellou\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003Esangriou\u003C\u002Fb\u003E. Kromě těchto kuchyní jsou v \u003Cb\u003EEvropě\u003C\u002Fb\u003E také velmi oblíbené pokrmy jako \u003Cb\u003Eněmecké klobásy\u003C\u002Fb\u003E, \u003Cb\u003Eanglické snídaně\u003C\u002Fb\u003E, \u003Cb\u003Eholandský sýr\u003C\u002Fb\u003E a mnoho dalšího.\u003C\u002Fp\u003E\n  \u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E také nabízí mnoho možností pro sportovní aktivity. Mezi nejpopulárnější sporty patří fotbal, hokej, tenis a cyklistika. Na kontinentu se také nachází mnoho golfových hřišť, lyžařských středisek a dalších sportovních zařízení. V posledních letech se stále více lidí zajímá o ekoturistiku, a tak se nabízí možnost podniknout pěší túru nebo cyklistický výlet a objevovat krásy evropské přírody.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EEvropa\u003C\u002Fb\u003E je jedním z nejlepších míst pro cestování, nabízí mnoho možností pro každého cestovatele. Díky rozmanitosti kontinentu si každý najde to svoje, co ho zaujme. Záleží pouze na vás, zda si zvolíte kulturní zážitky, přírodní krásy, sportovní aktivity nebo si jen tak užijete místní kuchyni a pohodu.\u003C\u002Fp\u003E",coordinates:[{latitude:47.497912,longitude:19.040235}],type_place:"continent",id_image_cover:j,id_image_hero:j,zoom:[{google:A,booking:A}],information_author:b,seo_tags:b,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:b}],placesCities:[{id:y,id_image_cover:B,importance:e,slug:C,type_place:a,name:"Athény"},{id:866,id_image_cover:D,importance:e,slug:E,type_place:a,name:"Chalkis"},{id:865,id_image_cover:F,importance:e,slug:G,type_place:a,name:"Chania"},{id:861,id_image_cover:H,importance:e,slug:I,type_place:a,name:"Herákleion"},{id:864,id_image_cover:J,importance:e,slug:K,type_place:a,name:"Ioánnina"},{id:867,id_image_cover:L,importance:e,slug:M,type_place:a,name:"Kavala"},{id:862,id_image_cover:N,importance:e,slug:O,type_place:a,name:"Larisa"},{id:n,id_image_cover:i,importance:e,slug:k,type_place:a,name:p},{id:859,id_image_cover:P,importance:e,slug:Q,type_place:a,name:"Soluň"},{id:863,id_image_cover:R,importance:e,slug:S,type_place:a,name:"Volos"}],imagesCities:[{id:D,name:E,source:f,type:a,author:"https:\u002F\u002Fcommons.wikimedia.org\u002Fwiki\u002FFile:%CE%A7%CE%B1%CE%BB%CE%BA%CE%AF%CE%B4%CE%B1_0067.jpg",created_at:h,updated_at:d},{id:L,name:M,source:f,type:a,author:g,created_at:h,updated_at:d},{id:F,name:G,source:f,type:a,author:g,created_at:h,updated_at:d},{id:J,name:K,source:f,type:a,author:g,created_at:h,updated_at:d},{id:R,name:S,source:f,type:a,author:g,created_at:h,updated_at:d},{id:N,name:O,source:f,type:a,author:g,created_at:h,updated_at:d},{id:B,name:C,source:f,type:a,author:g,created_at:h,updated_at:d},{id:P,name:Q,source:f,type:a,author:g,created_at:h,updated_at:d},{id:i,name:k,source:f,type:a,author:g,created_at:h,updated_at:d},{id:H,name:I,source:f,type:a,author:g,created_at:h,updated_at:d}]}],fetch:{"OrganismsoPlaceTeaserSpotsComponent:0":{spots:[],images:b},"OrganismsoSidebarListComponent:0":{events:[],images:b}},mutations:[]}}("city",null,"05-2023","2023-12-27T20:42:18.520959+00:00","biggest","\u002Fworld\u002Fcities\u002F","pixabay.com","2023-06-12T17:40:01.988214+00:00",587,4,"patra",1.5,398,860,89,"Patra",7,"booking",true,"recko","2 %","12-2023","09-2021","state",858,6,3,589,"atheny",604,"chalkis",602,"chania",586,"herakleion",601,"ioannina",603,"kavala",599,"larisa",588,"solun",600,"volos")));